    unfollow: { answer: 'no', rule: 'TikTok does not notify when you unfollow someone.', detail: 'Unfollowing is silent. They can only notice by checking their follower count or list.', except: ['Re-following later sends a fresh follow notification.'], sees: 'Nothing directly.', sure: 'Nothing to check.' },
    'remove-follower': { answer: 'no', rule: 'TikTok does not notify someone when you remove them as a follower.', detail: 'Removing a follower from your list is silent; they would have to visit your profile to see that they no longer follow you.', except: [], sees: 'Nothing directly.', sure: 'Nothing to check.' },
    block: { answer: 'no', rule: 'TikTok does not notify someone that you blocked them.', detail: 'A blocked user gets no alert. They can no longer see your videos, comment, message you or find your profile in search; opening your profile from a link shows it as unavailable.', except: [], sees: 'Nothing sent, but your profile becomes unreachable.', sure: 'Nothing to check.' },
