    'share-to-dm': { answer: 'no', rule: 'TikTok does not notify a creator when you share their video in a DM.', detail: 'Private shares count toward the video\'s share total; the creator sees the number, not the names.', except: ['Reposting puts the video on your profile and in your followers\' feeds, which is public.'], sees: 'A share count.', sure: 'Nothing to check.' },
