export const notifyPlatformBySlug = (slug) => NOTIFY_PLATFORMS.find((p) => p.slug === slug) || null;
export const notifyActionBySlug = (slug) => NOTIFY_ACTIONS.find((a) => a.slug === slug) || null;
export const notifyEntry = (platform, action) => NOTIFY[platform]?.[action] || null;
export const notifyPath = (platform, action = '') => `${NOTIFY_ROOT}/${platform}${action ? `/${action}` : ''}`;

/** Every page: [{ platform, action }], sorted by the hub order. */
export function allNotifyPages() {
  const out = [];
  for (const p of NOTIFY_PLATFORMS) for (const a of NOTIFY_ACTIONS) if (NOTIFY[p.slug]?.[a.slug]) out.push({ platform: p.slug, action: a.slug });
  return out;
}
/** Actions a platform has entries for, in hub order. */
export const notifyActionsFor = (platform) => NOTIFY_ACTIONS.filter((a) => NOTIFY[platform]?.[a.slug]).sort((a, b) => a.order - b.order);
/** Other platforms with an entry for the same action. */
export const notifyPlatformsFor = (action) => NOTIFY_PLATFORMS.filter((p) => NOTIFY[p.slug]?.[action]);
export const question = (action, platform) => action.q.replace('{p}', platform.name);

const year = () => new Date().getUTCFullYear();

/** Title: the question, then the answer in the first 50 characters. */
export function notifyCopy(platform, action, entry) {
  const q = question(action, platform);
  const label = answerLabel(entry.answer);
  const short = entry.answer === 'partly' ? 'Sometimes' : label;
  return {
    // The question and its answer always; the year and the platform's long name only when they fit.
    title: fitTitle(`${q} ${short} (${year()})`, `${question(action, { ...platform, name: shortPlatform(platform.name) })} ${short} (${year()})`, `${q} ${short}`, `${question(action, { ...platform, name: shortPlatform(platform.name) })} ${short}`),
    description: `${entry.rule} ${entry.sees} Checked ${NOTIFY_VERIFIED}, with the exceptions that catch people out.`,
    keyword: q.toLowerCase().replace(/\?$/, ''),
    h1: q,
    short,
  };
}

export function notifyFaq(platform, action, entry) {
  const name = platform.name;
  const others = notifyPlatformsFor(action.slug).filter((p) => p.slug !== platform.slug);
  const out = [
    { q: question(action, platform), a: `${entry.rule} ${entry.detail}` },
    { q: `What does the other person see when you ${action.short} on ${name}?`, a: entry.sees },
    { q: `Are there exceptions?`, a: entry.except.length ? entry.except.join(' ') : `No. The rule applies to every account type on ${name}, as of ${NOTIFY_VERIFIED}.` },
    { q: `Can a third-party app tell them that you ${action.short}?`, a: `No. ${name} does not expose this to apps, so any app that claims to is guessing or collecting your login. The only reliable signals are the ones ${name} shows itself.` },
    { q: `Has ${name} ever changed this?`, a: `Platforms change behaviour without notice, which is why this page carries a verification date (${NOTIFY_VERIFIED}). We re-check against ${name}'s help centre and the live app, and update the answer when something changes.` },
  ];
  if (others.length) out.push({ q: `Is it the same on ${others.slice(0, 3).map((p) => p.name).join(', ')}?`, a: others.slice(0, 4).map((p) => `${p.name}: ${notifyEntry(p.slug, action.slug).rule}`).join(' ') });
  return out;
}
